 text+='All signed query results/severe t/vuniononce>5pp/rescues/short<=5s-long and pointwise10000parentbootstrap seed20261022 remain in report/TSVs. Previously exposed benchmarks; notunknownconfirmation/familywise/equivalence claims. Freshscore walls are experimental CPU evaluation/IO, not deployment latency; inherited Source/expert acquisition nonzero.6actual child stages and controller exited0. Protected unrelated drafts, alloldscience/predictions/negative outcomes and paused/cancelled scopes untouched.\n'
 (P/'ANALYSIS.md').write_text(text);exits={p.stem:read(p)for p in(D/'exits').glob('*.json')};assert len(exits)==6 and all(x['actual_subprocess_wait']and x['exit_code']==0 for x in exits.values())
 for q in list(exits.values())+[dict(worker=read(D/'controller.json'))]:
  w=q['worker'];f=Path('/proc')/str(w['pid'])/'stat';assert not f.exists()or int(f.read_text().split()[21])!=w['startticks']
 atomic(P/'actual_cached_CPU_cost.json',dict(stage_clocks=exits,seal_prediction_clocks={ds:read(D/ds/'sealed.json')['elapsed_wall_seconds']for ds in COUNTS},nested_not_additive=True,new_Source=0,new_expert=0,new_model=0,new_GPU=0,new_optimizer=0,inherited_acquisition_cost_nonzero=True,deployment_latency=False))
 out=dict(status='both_full_tables_independently_rebuilt_rescored_audited_ROOTcomplete_PENDING_publication',scientific_fingerprint=validate()['fingerprint'],queries=COUNTS,new_official_checks=officialchecks,all_array_checks=allarrays,independent_scalar_checks=scalarchecks,root_paired_group_CI_checks=rootci,max_official_discrepancy=maxofficial,max_old_metric_discrepancy=maxold,max_independent_reference_discrepancy=maxref,controller_actual_wait=outer,all6actualchildstages_exit0=True,analysis_sha256=sha(P/'ANALYSIS.md'),audit_sha256={ds:sha(D/ds/'audit_receipt.json')for ds in COUNTS},all_pairing_exact=True,original_method_hard_anchor_contract_repaired=False,new_Source=0,new_expert=0,new_model=0,new_GPU=0,new_optimizer=0,old_results_or_paper_changed=False,time=time.time());atomic(D/'ROOT_completion.json',out);atomic(P/'completion_scalars.json',out);print(json.dumps({ds:{k:x['paired'][k]['v']for k in ['Full-ComboLog','Full-PureLogFixed','Full-ComboLinear','Full-PureLinearFixed']}for ds,x in reports.items()}))
